INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1322602-are322', 'stk-user6260', 'ARE 322', 'info', '{"desc": "are 322 - building mechanical systems\nare 325 - building illumination\nare 413 - construction management\nare 431 - building economy\nare 440 - solar energy in buildings\nare 457 - introduction to building maintenance management\nare 458 - quantitative methods in construction management\nare 459 - contracts and specifications\nare 490 - special topics in architectural engineering\n\nهالكورسات غير مقبولة كا الكتف … لانها من كلية علوم البيئة\n\nوقد تواصلت مع الدكتور حسن بدر … على كورس are 322 وقالي نفس الكلام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/xe-4xx/152412/11", "user": "user6260", "ts": 1390755656000, "tid": 152412, "pn": 11}}', 1390755656000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nevermind7-are322', 'stk-nevermind7', 'ARE 322', 'doc', '{"docs": [{"id": "stk-dr-f176816", "n": "Dr. Kim Daeung", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ARE 322 - Building Mechanical System\n\nالتحضير:\nيحضر بداية الكلاس، من الكشف بنادي، المتأخرين يحضرهم نهاية الكلاس\n\nطريقة الشرح :\nسلايدات يشرحها\n\nالكويزات :\nكويز كل أسبوعين مدته عشر دقائق\n\nالمياجر:\nثلاث مياجر وياخذ أفضل اثنين بينهم\nاختيارات 80% و مسألتين أو ثلاث عليهم 20% من الاختبار\n\nالفاينلات :\nالفاينال نفس نظام المياجر\n\nالقريد النهائي:\nِA+ ولو فيه أكثر يستاهل\n\nالصوت:\nصوته واضح بس اللهجة بالبداية ما بتفهم عنده نطق بعض الحروف، تحتاج كلاسين أو ثلاثة لين تستوعب لهجته\nمثلًا multiply كان ينطقها مالتيفلاي وقسّ على ذلك\n\nإضافات :\nالدكتور مجملًا كلاسه ممتع خفيف جدًا ويمر بسرعة، واللاب كان يمشينا بدري لو خلصنا.\nالدكتور من النوع اللي يحب ينكت ويجيب طاري الأفلام اللي يتابعها ويجيب نكت كثير منها، حاول تعطيه وجه وتضحك حتى لو ما فهمت.\nكطالب عمارة شفت المادة سهله مافيها صعوبة، الدكتور كيم “الكوري” مسهّل المادة بشكل كبير، مواضيعها متعدده ومثيرة للاهتمام.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1528087-are322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kim-daeung/176816/2", "user": "Nevermind7", "ts": 1611256919000, "tid": 176816, "pn": 2}}]}', 1611256919000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
